      note: '【令和9年度 前期選抜を実施する高等学校の「選抜において重視する要件」「検査内容」「選抜方法」(別表2・資料4)・全日制】選抜において重視する要件: (総合学科)〔総合的観点〕 ◎ 基本的な生活習慣が身についており、本校で実施するカリキュラム・学習内容・部活動等教育活動全般に対して強い興味・関心をもつ者で、かつ入学後、意欲的に学校生活を送る意志のある者〔個別観点〕次のいずれかに該当する者『学習について』 ○ 国語・社会・数学・理科・英語・芸術・体育等の各教科に関わって、優れた資質を持ち、得意分野の中から入学後も学習活動に意欲的である者 ○ 全ての教科に対して真面目に学習活動に取り組める者『部活動等について』 ○ スポーツ・文化活動等で優れた実績や能力があり、入学後もその活動を継続して行う意志のある者 ○ 個々の部活動において、意欲的に活動する意志のある者『学校生活について』 ○ 生徒会活動・学級活動で実績のある者 ○ ボランティア活動・人権活動に積極的に取り組める者『進路について』 ○ 将来、地域社会に根差し、地域の一員として社会貢献をする意欲のある者 ○ 自分の夢の実現に向け、 向上心を持って専門性を高めようと努力する者 ○ 四年制大学に進学を希望し、意欲的に学習に取り組める者。検査の実施概要: I=集団面接(1グループ20分程度) 総合学科での学習に対する興味・関心や意欲、進路に関する目的意識 等について応答する。 / 作文=45分・600~800字 / II=国語、英語 / 学力検査=数学、英語 / III=集団面接(1グループ20分程度) 総合学科での学習に対する興味・関心や意欲、進路に関する目的意識 等について応答する。 / 次のいずれか1つを事前に選択する。=検査時間:120分(休憩を含む) 内容:静物デッサン、デッサンについての感想文(10分) 持参用具:鉛筆、消しゴム(練り消しゴム可) ※高等学校で用意するもの:用紙(B3M 画用紙ボード) / 実技検査芸術(書道)=検査時間:120分(休憩を含む) 内容:実技〔毛筆(半紙)・硬筆〕、実技作品についての感想文 (10分) 持参用具:太筆、細筆、墨汁(固形墨可)、硯、鉛筆、消しゴム、練 習用半紙、文鎮 ※高等学校で用意するもの:下敷き、清書用紙 / 実技検査体育=1 共通検査 25m往復走、反復横跳び、立ち幅跳び、長座体前屈を全ての志願者 に課す。 2 選択種目検査 1 次の種目から、志願者が事前に選択した1種目とする。 陸上競技(100m走、800m走、砲丸投げ、走り高跳び、走 り幅跳び)・ サッカー・バスケットボール・バレーボール・卓球・ ソフトボール・器械運動(マット運動)・剣道・レスリング・ゴルフ ・ハンドボール・ソフトテニス ※陸上競技は、( )内の5種目から1種目を選択する。 2 内容は、基本的な技能・技術・動作を中心とする。。選抜方法: I 1 選抜資料の取扱い:  (1) 調 査 書 点数化する。 評定(第3学年の各教科の評定の合計を2倍) 90点満点 学級活動・生徒会活動、取得資格、 スポーツ・文化・地域活動の実績 最高 10点 合 計 100点 (2) 面 接 A、B、C、Dの4段階で評価し、点数化する。(10点満点) (3) 作 文 A、B、C、Dの4段階で評価し、点数化する。(10点満点) 2 選抜方法:  (1)~(3)の合計点数をもとに、面接及び作文の評価、調査書、「自己推薦書」の記載事項を 考慮して総合的に選抜する。 II 1 選抜資料の取扱い:  (1) 調 査 書 点数化する。 1 評定(第3学年の各教科の評定の合計) 45点満点 2 学級活動・生徒会活動、取得資格、 スポーツ・文化・地域活動の実績 最高10点 (2) 学力検査 国語、英語または数学、英語(各教科50点) 100点 2 選抜方法:  (1)1の評定得点と(1)2、(2)の合計点数の2つをもとに、調査書、「自己推薦書」の記載 事項を考慮して総合的に選抜する。 III 1 選抜資料の取扱い:  (1) 調 査 書 点数化する。 1 評定(第3学年の各教科の評定の合計) 45点満点 2 学級活動・生徒会活動、取得資格、 スポーツ・文化・地域活動の実績 最高10点 (2) 面 接 A、B、C、Dの4段階で評価し、点数化する。(10点満点) (3) 実技検査 90点 2 選抜方法:  (1)1の評定得点と(1)2、(2)、(3)の合計点数の2つをもとに、面接の評価、調査書、「自 己推薦書」の記載事項を考慮して総合的に選抜する。。学校の特色の本文は未収録。',
