      note: '【令和9年度 前期選抜を実施する高等学校の「選抜において重視する要件」「検査内容」「選抜方法」(別表2・資料4)・全日制】選抜において重視する要件: (普通科) ○ 高い志を持ち、希望進路の実現に向けて意欲を持って持続的に学習に取り組む者 ○ 部活動や生徒会活動または地域との連携等に意欲的に取り組む意志のある者(生産経済科) ○ 農業・環境・福祉に関して興味・関心、意欲があり、将来、就農を志す者または関連する分野への進学や就職を強く希望する者 ○ 各種検定や資格取得に意欲のある者 ○ 部活動や生徒会活動または地域との連携等に意欲的に取り組む意志のある者(環境創造科) ○ 専門分野の学習に興味・関心、意欲があり、明確な進路希望をもち、その実現に向けて意欲的に学習に取り組む者 ○ 各種検定や資格取得に意欲のある者 ○ 部活動や生徒会活動または地域との連携等に意欲的に取り組む意志のある者(食物調理科) ○ 食物に関する分野で、特に調理、製菓に興味・関心、意欲があり、高度な知識・技術を習得し、将来、食に関する分野への進路を強く希望する者。検査の実施概要: 面接=個人面接(7分程度) 生産経済科への志望動機、学習したい専門分野の内容、取得したい資格、将来の進路 について応答する。また、農業・環境・福祉分野に関する興味・関心や基礎的な知識に ついて応答する。 / 作文=45分・2題・各200字程度。選抜方法: 1 選抜資料の取扱い:  (1) 調 査 書 点数化する。(第1~3学年の各教科の評定の合計 135点満点) (2) 面 接 A、B、C、D、Eの5段階で評価する。 (3) 作 文 A、B、Cの3段階で評価する。 2 選抜方法:  次の各段階に該当する受検者について順に、調査書及び「自己推薦書」の記載事項を考慮して 総合的に選抜する。 (1) 第1段階 調査書得点の順位が募集人数の70%以内であることと、面接の評価がC段階以 上及び作文の評価がB段階以上であることの両方の条件を満たす者 (2) 第2段階 面接の評価がC段階以上及び作文の評価がB段階以上である者のうち、調査書の 記載事項において「選抜において重視する要件」に特に合致していると認められる 者 (3) 第3段階 第1段階及び第2段階で合格となった者を除く全ての受検者。学校の特色の本文は未収録。',
