      note: '【令和9年度 前期選抜を実施する高等学校の「選抜において重視する要件」「検査内容」「選抜方法」(別表2・資料4)・全日制】選抜において重視する要件: 〔商業科、情報処理科、国際科共通〕 ○ 学習成績に優れ、入学後も高い学習意欲を維持できる者 ○ 探究活動に意欲的に取り組むことができる者 ○ 学科の特性を生かして大学進学・就職等の進路希望を実現しようとする者 ○ スポーツ・文化活動やボランティア活動または生徒会活動等に意欲をもって取り組む姿勢を有する者(商業科) ○ 商業の学習に興味と関心を有する者 ○ 簿記をはじめとする各種検定の取得に取り組む意欲を有する者(情報処理科) ○ コンピュータの学習に興味と関心を有する者 ○ 情報、簿記等の各種検定の取得に取り組む意欲を有する者(国際科) ○ 英語学習への意欲にあふれ、強い興味を有する者 ○ 英語、簿記等の各種検定の取得に取り組む意欲を有する者。検査の実施概要: 面接=集団面接(1グループ20分程度) 志望動機、期待する高校生活、中学校時代の活動状況等について応答する。 / 学力検査=英語。選抜方法: 1 選抜資料の取扱い:  (1) 調 査 書 点数化する。 評定(第1~3学年の各教科の評定を換算) 70点満点 スポーツ・文化活動の実績等、資格等 最高20点 合 計 90点 (2) 面 接 A、B、C、D、Eの5段階で評価する。 (3) 学力検査 50点 2 選抜方法:  次の各段階に該当する受検者について順に、調査書及び「自己推薦書」の記載事項を考慮し て総合的に選抜する。 (1) 第1段階 面接の評価がC段階以上である者のうち、調査書得点の順位が募集人数のおよ そ100%以内であることと、学力検査得点の順位が募集人数のおよそ80%以 内であることの両方の条件を満たす者 (2) 第2段階 面接の評価がC段階以上である者のうち、調査書得点の順位が募集人数のおよ そ100%以内であることと、学力検査得点の順位が募集人数のおよそ90%以 内であることの両方の条件を満たす者 (3) 第3段階 第1段階及び第2段階で合格となった者を除く全ての受検者。学校の特色の本文は未収録。',
