      interviewRequired: true,
      note: '【令和9年度 スポーツ特別枠選抜を実施する高等学校の「募集競技」「応募資格」「実技検査」「選抜方法」(別表6・資料8)】募集競技(募集学科 募集人数): 水泳競技（競泳）（男子） （普通科 ２人以内、 情報ビジネス科 ２人以内、 システム工学科 １人以内） / 水泳競技（競泳）（女子） （普通科 ３人以内、 情報ビジネス科 ２人以内）。応募資格: （水泳競技（競泳）(男子）（女子）） / 次の(1)～(2)の条件を全て満たすこと / (1) 中学校の部活動又は地域のクラブチームに所属し、積極的に活動した者 / (2) 本校の部活動に所属して３年間継続をするとともに、本校における学業と両立させる強い意志がある者。検査の実施概要: 実技検査 / 水泳競技（競泳）（男子） / 水泳競技（競泳）（女子）(1) ２００ｍ個人メドレー / (2) ５０ｍ自由形 / ※タイム測定を実施する。 / ただし、天候や施設・設備の状況により検査会場が使用できない場合 / は以下の(3)・(4)・(5)を行う。 / (3) 反復横跳び / (4) 垂直跳び / (5) シャトルラン / ※ 運動能力テストの実施要項に従って実施する。選抜方法: １ 選抜資料の取扱い / (1) 調 査 書 点数化する。 普通科（第３学年の各教科の評定の合計 ４５点満点） / 情報ビジネス科（第３学年の各教科の評定の合計を２倍 ９０点満点） / システム工学科（第３学年の各教科の評定の合計を２倍 ９０点満点） / (2) 面 接 次の４つの項目について評価し、Ａ、Ｂ、Ｃで評価する。 / ・本校、本学科を志望する動機、目的意識 / ・学科の内容についての理解 / ・高校生活への意欲 / ・面接態度（応答の的確さ、明瞭さなど） / (3) 学力検査 １００点（数学５０点、英語５０点） / (4) 実技検査 実技検査の各内容を点数化する。 （３０点満点） / ２ 選抜方法 / (1)～(4)をもとに、調査書及び「スポーツ特別枠自己推薦書」の記載事項（過去の競技実績等）を考慮して総合的に選抜する。',
